output_text:
[
  {
    "id": "cart_must_be_taken",
    "text": "At the beginning of the trip the shopper is obliged to take the available cart from the start cart station.",
    "abstraction": {
      "state_properties": {
        "start_cart_station": "at(1,5)",
        "cart_available_at_start": "cartAt(1,5)"
      },
      "events": {
        "take_start_cart": {
          "pre": {
            "and": [
              "start_cart_station",
              "cart_available_at_start",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_start_cart"
    }
  },
  {
    "id": "items_only_with_cart",
    "text": "A shopper is prohibited from picking up shelf items unless they are currently pushing or holding a cart.",
    "abstraction": {
      "state_properties": {
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "uncarted_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "uncarted_item_pickup"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "The shopper is prohibited from carrying groceries by hand instead of transporting them in the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_by_hand"
    }
  },
  {
    "id": "return_cart_to_bay",
    "text": "After taking a cart, the shopper is obliged to return it to the designated return bay before the trip ends.",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)"
      },
      "events": {
        "cart_taken": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "cart_returned_to_bay": {
          "pre": {
            "and": [
              "cart_return_bay",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_taken",
      "discharge": "cart_returned_to_bay"
    }
  },
  {
    "id": "no_cart_abandonment",
    "text": "The shopper is prohibited from leaving the cart anywhere other than the designated return bay.",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)",
        "not_at_cart_return_bay": {
          "not": "cart_return_bay"
        }
      },
      "events": {
        "leave_cart_outside_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "not_at_cart_return_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_bay"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "The shopper is prohibited from exiting the supermarket while still in possession of the cart.",
    "abstraction": {
      "state_properties": {
        "with_cart": "hasCart"
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "EXIT",
              "with_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "cart_free_checkout_corridor",
    "text": "Carts are prohibited in the front checkout and exit corridor, so the shopper must park the cart before walking through that area.",
    "abstraction": {
      "state_properties": {
        "checkout_corridor": {
          "or": [
            "at(7,2)",
            "at(8,2)",
            "at(9,2)",
            "at(7,3)",
            "at(8,3)",
            "at(9,3)",
            "at(7,4)",
            "at(8,4)",
            "at(9,4)",
            "at(7,5)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "cart_in_checkout_corridor": {
          "and": [
            "hasCart",
            "checkout_corridor"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_in_checkout_corridor"
    }
  },
  {
    "id": "must_park_at_return_bay",
    "text": "Once the shopper reaches the cart return bay with a cart, they are prohibited from moving onward with it rather than parking it.",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)",
        "with_cart_at_return_bay": {
          "and": [
            "hasCart",
            "cart_return_bay"
          ]
        }
      },
      "events": {
        "move_cart_out_of_return_bay": {
          "pre": {
            "and": [
              "with_cart_at_return_bay",
              "MOVE"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "move_cart_out_of_return_bay"
    }
  }
]
